def calcular_promedios(notas_alumnos: dict[str, list[float]]) -> dict[str, float]:
    promedios = {}
    for alumno, notas in notas_alumnos.items():
        promedios[alumno] = sum(notas) / len(notas)
    return promedios

registro = {"Ana": [90.0, 95.0], "Carlos": [80.0, 85.0]}
print(calcular_promedios(registro))

